{
  "name": "@felipegenef/opencode-sebas",
  "version": "1.0.3",
  "description": "Sebas, the electronic butler for LLM-assisted work: speaks your agents' messages through a local text-to-speech daemon, parks the messages that collide onto a system notification card with a single Listen button, and keeps one voice at a time. Ships the voice MCP, the butler persona and the notification cards as one OpenCode plugin.",
  "license": "MIT",
  "publishConfig": {
    "access": "public"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/felipegenef/sebas.git"
  },
  "type": "module",
  "module": "dist/index.js",
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    }
  },
  "files": [
    "dist",
    "index.js",
    "mcp",
    "notify",
    "README.md",
    "LICENSE",
    "!**/__pycache__/**",
    "!**/*.pyc"
  ],
  "scripts": {
    "build": "bun build src/index.ts --outdir dist --target node --format esm --external '@opencode/plugin' && tsc -p tsconfig.build.json",
    "check": "tsc --noEmit",
    "test": "bun test"
  },
  "dependencies": {
    "@opencode/plugin": "^2.0.18"
  },
  "devDependencies": {
    "@types/bun": "^1.3.0",
    "@types/node": "^22.0.0",
    "typescript": "^5.9.0"
  }
}
